+pub struct AdDrops(Mutex<Vec<DroppedAd>>);
+
+impl AdDrops {
+    pub fn extend(&self, drops: impl IntoIterator<Item = DroppedAd>) {
+        self.0
+            .lock()
+            .unwrap_or_else(PoisonError::into_inner)
+            .extend(drops);
+    }
+
+    pub fn take(&self) -> Vec<DroppedAd> {
