fn as_post(item: &FeedItem) -> Option<&ScoredPost> {
    match &item.item {
        Some(feed_item::Item::Post(post)) => Some(post),
        _ => None,
    }
}

fn post_tweet_id(item: &FeedItem) -> Option<u64> {
    as_post(item).map(|post| post.tweet_id)
}

